update u_user_notification as t set t.is_del = #{isDel}

    ,t.community_id = #{communityId}

where 1=1

    and t.id= #{id}


    and t.community_id= #{communityId}


    and t.user_id = #{userId}


    and t.notification_id = #{notificationId}

mapper.insert:
insert into u_user_notification_reads(user_notification_id, user_id)
select a.id as user_notification_id, #{userId} as user_id
FROM u_user_notifications as a
left join u_notification_types as b on b.type=a.type
left join u_user_notification_reads as c on c.user_notification_id=a.id and c.user_id=#{userId}
where a.is_del=0 and a.sent_time>=(select create_time from u_user where user_id=#{userId})
and c.read_time is null

    and (a.user_id=#{userId} or a.user_id='0')


    and a.type = #{type}


    and a.community_id = #{communityId}

mapper.select:
select t.id, t.user_id as userId, t.notification_id as notificationId, t.name, t.title, t.content, t.type, t.page_type as pageType, t.app_page_url as appPageUrl, t.h5_page_url as h5PageUrl, t.community_id as communityId, t.sent_time as sentTime, t.create_time as createTime, t.update_time as updateTime, case when r.id is not null then 1 else 0 end as isRead, r.read_time as readTime, t.sender_name as senderName from u_user_notifications as t left join u_user_notification_reads as r on r.user_notification_id=t.id where t.is_del = 0
and t.community_id = #{communityId}
and t.user_id = #{userId}
and t.type = #{type}
and r.id is null
and r.id is not null
order by t.create_time desc
limit #{page}, #{row}

select count(1) count
from u_user_notifications as t
left join u_user_notification_reads as r on r.user_notification_id=t.id
where t.is_del = 0

    and t.community_id = #{communityId}


    and t.user_id = #{userId}


    and t.type = #{type}


    and r.id is null


    and r.id is not null
